parameters.jsCode:
// Get the AI response text
const aiResponse = $input.item.json.output || "";

let selectedAgent = "";
let reason = "";
let userMessage = "";

// Extract agent, reason, and user message from the AI response
if (aiResponse.includes("SELECTED AGENT:")) {
  // Extract agent ID
  const agentMatch = aiResponse.match(/SELECTED AGENT: ([a-zA-Z0-9_-]+)/);
  selectedAgent = agentMatch && agentMatch[1] ? agentMatch[1] : "";

  // Extract reason
  const reasonMatch = aiResponse.match(/REASON: ([\s\S]+?)($|\n|USER_MESSAGE:)/);
  reason = reasonMatch && reasonMatch[1] ? reasonMatch[1].trim() : "";

  // Extract original user message
  const messageMatch = aiResponse.match(/USER_MESSAGE: ([\s\S]+?)($|\n)/);
  userMessage = messageMatch && messageMatch[1] ? messageMatch[1].trim() : "";
} else if (aiResponse.includes("CLARIFICATION NEEDED")) {
  selectedAgent = "clarification-needed";
  const questionMatch = aiResponse.match(/QUESTION: ([\s\S]+?)($|\n|USER_MESSAGE:)/);
  reason = questionMatch && questionMatch[1] ? questionMatch[1].trim() : "";
  const messageMatch = aiResponse.match(/USER_MESSAGE: ([\s\S]+?)($|\n)/);
  userMessage = messageMatch && messageMatch[1] ? messageMatch[1].trim() : "";
}

// Extract conversation history from the webhook input
let chatHistory = [];
try {
  // Access conversation history from the webhook payload
  const webhookInputs = $('Webhook').all();
  if (webhookInputs && webhookInputs[0] && webhookInputs[0].json && webhookInputs[0].json.body) {
    const conversationHistory = webhookInputs[0].json.body.conversationHistory;
    if (Array.isArray(conversationHistory)) {
      // Convert OpenWebUI format to LangChain format for consistency
      chatHistory = conversationHistory.map(msg => ({
        id: ["langchain_core", "messages", msg.role === "user" ? "HumanMessage" : "AIMessage"],
        kwargs: {
          content: msg.content
        }
      }));
    }
  }
  console.log("Chat history retrieved from webhook:", chatHistory.length, "messages");
} catch (error) {
  console.log("Could not access conversation history from webhook:", error);
  chatHistory = [];
}

// Return the fields required by the sub-workflows
return {
  json: {
    input: userMessage,
    reason: reason,
    selectedAgent: selectedAgent,
    chatHistory: chatHistory
  }
};

// Get the reason field which contains the clarification question for this flow
const reason = $input.item.json.reason || "";
let clarificationQuestion = "Could you please provide more information about what you're trying to do?";

// The reason field should contain the clarification question
if (reason && reason.length > 0) {
  clarificationQuestion = reason;
} else {
  // Fallback: try to extract from any available text
  const input = $input.item.json.input || "";
  if (input.includes("QUESTION:")) {
    const match = input.match(/QUESTION: (.*?)($|\n)/);
    if (match && match[1]) {
      clarificationQuestion = match[1].trim();
    }
  }
}

return {
  json: {
    response: clarificationQuestion
  }
};

